-- Synthetic plan values below test the algorithm only; they are not an AQL table.
-- Run with the progressive migration in the same transaction, then ROLLBACK.
do $$
declare u uuid; username text; product text; before_legacy jsonb; legacy bigint; lot_data jsonb; round_data jsonb;
 r jsonb; v_lot bigint; session_id bigint; aql_lot bigint; draft uuid; started timestamptz; ended timestamptz; updated timestamptz; failed boolean; baseline timestamptz:=clock_timestamp(); chem_code text; chem_lot bigint; chem_token uuid; chem_data jsonb; tc jsonb;
begin
 select user_id,user_roles.username into u,username from user_roles where role='admin' limit 1;
 select ma_sp into product from master_products order by ma_sp limit 1;
 if u is null or product is null then raise exception 'Missing fixture'; end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 select id,to_jsonb(l) into legacy,before_legacy from iqc_lots l order by id limit 1;
 lot_data:=jsonb_build_object('supplier','BRV','product_code',product,'product_name','Fixture','lot_no','IQC-PROGRESSIVE-TEST','lot_qty',100,'pham_vi','Đúc','inspection_type','Kiểm tra 100%');
 r:=iqc_luu_lan_kiem(null,lot_data,null,gen_random_uuid());v_lot:=(r->>'lot_id')::bigint;
 if exists(select 1 from iqc_lan_kiem where lot_id=v_lot) or (select status from iqc_lots where id=v_lot)<>'Chưa lấy hàng' or (select received_at from iqc_lots where id=v_lot)<baseline then raise exception 'LOT registration wrong'; end if;
 draft:=gen_random_uuid();r:=iqc_bat_dau_lan_kiem(draft,v_lot);started:=(r->>'bat_dau_luc')::timestamptz;
 if started<baseline or exists(select 1 from iqc_lan_kiem where lot_id=v_lot) then raise exception 'Draft counted as completed'; end if;
 round_data:=jsonb_build_object('bat_dau_id',draft,'ngay_kiem','1900-01-01','nguoi_kiem',username,'so_kiem',40,'so_ok',35,'so_ng',5,'loi','[{"ten_loi":"Xước","so_luong":5},{"ten_loi":"Ba via","so_luong":5}]'::jsonb);
 r:=iqc_luu_lan_kiem(v_lot,null,round_data,gen_random_uuid());session_id:=(r->>'lan_kiem_id')::bigint;
 select bat_dau_luc,ket_thuc_luc into started,ended from iqc_lan_kiem where id=session_id;
 if ended<started or ended>clock_timestamp() or (select ngay_kiem from iqc_lan_kiem where id=session_id)<>(started at time zone 'Asia/Ho_Chi_Minh')::date or (select result from iqc_lots where id=v_lot)<>'' or (select ng_qty from iqc_lots where id=v_lot)<>5 then raise exception 'Server timing or quality separation failed'; end if;
 draft:=gen_random_uuid();perform iqc_bat_dau_lan_kiem(draft,v_lot);
 perform iqc_luu_lan_kiem(v_lot,null,round_data||jsonb_build_object('bat_dau_id',draft,'so_kiem',60,'so_ok',60,'so_ng',0,'loi','[]'::jsonb),gen_random_uuid());
 if (select result from iqc_lots where id=v_lot)<>'' then raise exception 'NG pieces automatically concluded LOT'; end if;
 select updated_at into updated from iqc_lots where id=v_lot;
 perform iqc_phan_quyet_lot(v_lot,'OK',updated,'Đã phân loại và xử lý theo tiêu chuẩn thử');
 if (select iqc_ket_luan from iqc_lots where id=v_lot)<>'OK' then raise exception 'Explicit disposition failed'; end if;
 select sua_luc into updated from iqc_lan_kiem where id=session_id;
 perform iqc_sua_thoi_gian_lan_kiem(session_id,started-interval '1 hour',ended,updated,'Đối chiếu phiếu thử');
 if not exists(select 1 from iqc_lich_su where loai='sua_thoi_gian_lan_kiem' and khoa=session_id::text) then raise exception 'Time correction audit missing'; end if;
 lot_data:=lot_data||'{"lot_no":"IQC-PROGRESSIVE-AQL","lot_qty":1000,"inspection_type":"Kiểm tra AQL","aql":"1.0"}'::jsonb;
 r:=iqc_luu_lan_kiem(null,lot_data,null,gen_random_uuid());aql_lot:=(r->>'lot_id')::bigint;
 draft:=gen_random_uuid();perform iqc_bat_dau_lan_kiem(draft,aql_lot);
 perform iqc_luu_lan_kiem(aql_lot,null,round_data||jsonb_build_object('bat_dau_id',draft,'so_kiem',10,'so_ok',9,'so_ng',1,'loi','[]'::jsonb),gen_random_uuid());
 select updated_at into updated from iqc_lots where id=aql_lot;
 failed:=false;begin perform iqc_phan_quyet_lot(aql_lot,'OK',updated,'Chưa có kế hoạch');exception when others then failed:=true;end;
 if not failed then raise exception 'AQL accepted without approved plan'; end if;
 perform iqc_luu_cau_hinh_aql('fixture','fixture-v1','FIXTURE ONLY — synthetic test values','II','1.0','single-normal', '{"lotRanges":[{"min":1,"max":null,"code":"A"}],"plans":{"A":{"use":"B"},"B":{"sample":10,"ac":1,"re":2}}}'::jsonb, array[product], true);
 if (iqc_tra_ke_hoach_aql(aql_lot)->>'ma_chu')<>'A' or (iqc_tra_ke_hoach_aql(aql_lot)->>'mau_yeu_cau')::int<>10 then raise exception 'AQL configured lookup failed'; end if;
 failed:=false;begin perform iqc_duyet_ke_hoach_aql(aql_lot,20,1,2,'wrong',updated);exception when others then failed:=true;end;
 if not failed then raise exception 'AQL plan changed outside approved configuration'; end if;
 perform iqc_duyet_ke_hoach_aql(aql_lot,10,1,2,'FIXTURE ONLY — synthetic test values',updated);
 select updated_at into updated from iqc_lots where id=aql_lot;
 perform iqc_phan_quyet_lot(aql_lot,'OK',updated,'Theo kế hoạch thử được duyệt');
 if (select result from iqc_lots where id=aql_lot)<>'OK' or (select lot_qty from iqc_lots where id=aql_lot)<>1000 then raise exception 'AQL sample disposition failed'; end if;
 draft:=gen_random_uuid();perform iqc_bat_dau_lan_kiem(draft,aql_lot);
 perform iqc_luu_lan_kiem(aql_lot,null,round_data||jsonb_build_object('bat_dau_id',draft,'so_kiem',1,'so_ok',1,'so_ng',0,'loi','[]'::jsonb),gen_random_uuid());
 select updated_at into updated from iqc_lots where id=aql_lot;
 failed:=false;begin perform iqc_phan_quyet_lot(aql_lot,'OK',updated,'Vượt số mẫu');exception when others then failed:=true;end;
 if not failed or coalesce((select result from iqc_lots where id=aql_lot),'')<>'' then raise exception 'AQL over-sample accepted without reconciliation'; end if;
 perform iqc_luu_cau_hinh_aql('fixture','fixture-v2','FIXTURE ONLY — new version','I','0.65','single-normal', '{"lotRanges":[{"min":1,"max":null,"code":"C"}],"plans":{"C":{"sample":20,"ac":0,"re":1}}}'::jsonb, array[product], true);
 if (select count(*) from iqc_aql_cau_hinh where nhom='fixture' and da_duyet)<>1 or not exists(select 1 from iqc_lich_su where loai='ngung_cau_hinh_aql') then raise exception 'AQL version transition failed'; end if;
 if (select aql from iqc_aql_ke_hoach where lot_id=aql_lot)<>'1.0' or (select phien_ban from iqc_aql_ke_hoach where lot_id=aql_lot)<>'fixture-v1' then raise exception 'Approved historic AQL plan changed'; end if;
 lot_data:=lot_data||'{"lot_no":"IQC-PROGRESSIVE-AQL-065","aql":"0.65"}'::jsonb;
 r:=iqc_luu_lan_kiem(null,lot_data,null,gen_random_uuid());aql_lot:=(r->>'lot_id')::bigint;
 if (iqc_tra_ke_hoach_aql(aql_lot)->>'aql')<>'0.65' or (iqc_tra_ke_hoach_aql(aql_lot)->>'mau_yeu_cau')::int<>20 then raise exception 'Group AQL configuration not respected'; end if;
 select updated_at into updated from iqc_lots where id=aql_lot;
 perform iqc_duyet_ke_hoach_aql(aql_lot,20,0,1,'fixture',updated);
 if (select aql from iqc_aql_ke_hoach where lot_id=aql_lot)<>'0.65' then raise exception 'AQL defaulted to 1.0'; end if;
 select n.ma_nvl into chem_code from nvl_materials n join vat_lieu_mac m on m.ma_mac=n.ma_mac where n.nhom_vat_tu='kim_loai' and m.loai_kim_loai='nhom' limit 1;
 if chem_code is null then raise exception 'Missing chemical fixture'; end if;
 chem_token:=gen_random_uuid();r:=iqc_dang_ky_lot_hoa_hoc(chem_token,chem_code,'IQC-PROGRESSIVE-CHEM','TEST NCC',500,'kg');chem_lot:=(r->>'id')::bigint;
 if (iqc_dang_ky_lot_hoa_hoc(chem_token,chem_code,'IQC-PROGRESSIVE-CHEM','TEST NCC',500,'kg')->>'id')::bigint<>chem_lot then raise exception 'Chemical registration retry duplicated'; end if;
 if not exists(select 1 from iqc_lots where id=chem_lot and iqc_khoi_luong_hoa_hoc=500 and iqc_don_vi_hoa_hoc='kg' and hoa_hoc_json is null and coalesce(result,'')='' and lot_qty=0) then raise exception 'Chemical LOT registration not pending'; end if;
 select updated_at into updated from iqc_lots where id=chem_lot;tc:=iqc_tc_hoa_hoc(chem_code,current_date);
 chem_data:=jsonb_build_object('request_id',gen_random_uuid(),'ma_nvl',chem_code,'ngay_kiem',current_date,'ca_kiem','Ca ngày','lot_no','IQC-PROGRESSIVE-CHEM','supplier','TEST NCC','inspector',username,'results','{}'::jsonb,'xac_nhan',false,'updated_at',updated,'id_tieu_chuan',tc->'tieu_chuan'->'id');
 perform iqc_luu_hoa_hoc(chem_lot,chem_data);
 if (select count(*) from iqc_phan_tich_hoa_hoc_lich_su where lot_id=chem_lot)<>1 or (select iqc_khoi_luong_hoa_hoc from iqc_lots where id=chem_lot)<>500 then raise exception 'Chemical analysis not linked to registered LOT'; end if;
 failed:=false;begin perform iqc_dang_ky_lot_hoa_hoc(gen_random_uuid(),chem_code,'IQC-PROGRESSIVE-CHEM','TEST NCC',500,'kg');exception when others then failed:=true;end;
 if not failed then raise exception 'Duplicate chemical LOT accepted'; end if;
 failed:=false;begin perform iqc_luu_hoa_hoc(null,chem_data||jsonb_build_object('request_id',gen_random_uuid(),'updated_at',null));exception when others then failed:=true;end;
 if not failed then raise exception 'Duplicate chemical LOT bypassed through old analysis API'; end if;
 if legacy is not null and (select to_jsonb(l) from iqc_lots l where id=legacy) is distinct from before_legacy then raise exception 'Legacy LOT changed'; end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 failed:=false;begin perform iqc_bat_dau_lan_kiem(gen_random_uuid(),v_lot);exception when others then failed:=true;end;
 if not failed then raise exception 'Unauthorized start'; end if;
end $$;
